changeSet.sql:
INSERT INTO parser (name, description, dataset_name, list_type, website_url, plugin_id, plugin_url, data_source_type, parser_kind, source_location, parameters, refresh_hours, retention_months, licence, attribution, notes, enabled, created_at) VALUES ('PEP Autriche – Hautes juridictions', 'Membres et suppléants du VfGH, juges de l''OGH et du VwGH, d''après les pages officielles des cours (catégorie AT-d)', 'at_pep_high_courts', 'PEP', 'https://www.vfgh.gv.at/', 'at-pep-institutions', 'D:/test parser 2/plugins/swiftcheck-aml-at-pep-institutions-0.0.1-SNAPSHOT.jar', 'PLUGIN_MANAGED', 'WEB_PAGE', NULL, '{"keys": "vfgh,vfgh_substitutes,ogh,vwgh", "delayMs": "1500"}', 168, 12, 'Sites officiels des cours : citer la source', 'VfGH, OGH et VwGH (vfgh.gv.at, ogh.gv.at, vwgh.gv.at)', 'Même plugin que at_pep_audit_and_central_bank et at_pep_land_governments ; le paramètre keys choisit les institutions. Adresses dans institutions.json. Aucun nom embarqué.', TRUE, NOW());
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les 14 membres et 6 suppléants du VfGH en fonction.', 'Pas de dates de nomination sur les pages ; anciens juges non nommés.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'AT-d' AND f.label LIKE 'Juge de la Cour constitutionnelle%' AND p.dataset_name = 'at_pep_high_courts';
INSERT INTO pep_function_parser (function_id, parser_id, completeness, includes_former, covered_scope, gaps) SELECT f.id, p.id, 'COMPLETE', FALSE, 'Les juges de l''OGH (une soixantaine) et du VwGH (une centaine) en fonction.', 'Pas de dates de nomination sur les pages ; anciens juges non nommés.' FROM pep_function f JOIN pep_category c ON c.id = f.category_id, parser p WHERE c.code = 'AT-d' AND f.label LIKE 'Juge de la Cour suprême (OGH)%' AND p.dataset_name = 'at_pep_high_courts';
